using System;

// PROGRAM: Menerapkan Enkapsulasi Kaya (Rich Domain Model)
public class SecureWallet
{
    public string Owner { get; init; }
    public decimal Balance { get; private set; }

    public SecureWallet(string owner, decimal initialDeposit)
    {
        if (string.IsNullOrWhiteSpace(owner))
            throw new ArgumentException("Owner tidak boleh kosong.");
        if (initialDeposit < 0)
            throw new ArgumentException("Deposit awal tidak boleh negatif.");

        Owner = owner;
        Balance = initialDeposit;
    }

    public void Deposit(decimal amount)
    {
        if (amount <= 0) throw new ArgumentException("Nominal deposit harus positif.");
        Balance += amount;
    }

    public bool TryWithdraw(decimal amount)
    {
        if (amount <= 0 || Balance < amount) return false;
        Balance -= amount;
        return true;
    }
}

public class Program
{
    public static void Main()
    {
        var wallet = new SecureWallet("Ahmad", 1_000_000m);
        Console.WriteLine($"Pemilik: {wallet.Owner} | Saldo: Rp {wallet.Balance:N0}");

        wallet.Deposit(500_000m);
        Console.WriteLine($"Setelah deposit: Rp {wallet.Balance:N0}");

        bool ok = wallet.TryWithdraw(2_000_000m);
        Console.WriteLine($"Penarikan 2 Juta berhasil? {ok} (Saldo tetap: Rp {wallet.Balance:N0})");
    }
}

