using System;

public class AccountLedger
{
    public string AccountId { get; init; }
    public decimal Balance { get; private set; }

    public AccountLedger(string accountId, decimal initialBalance)
    {
        if (string.IsNullOrWhiteSpace(accountId))
            throw new ArgumentException("AccountId required.");
        if (initialBalance < 0)
            throw new ArgumentException("Initial balance cannot be negative.");

        AccountId = accountId.Trim();
        Balance = initialBalance;
    }

    public void Credit(decimal amount)
    {
        if (amount <= 0)
            throw new ArgumentException("Credit amount must be positive.");
        Balance += amount;
    }

    public void Debit(decimal amount)
    {
        if (amount <= 0)
            throw new ArgumentException("Debit amount must be positive.");
        if (Balance < amount)
            throw new InvalidOperationException("Insufficient funds");
        Balance -= amount;
    }
}

public class Program
{
    public static void Main()
    {
        var ledger = new AccountLedger("ACC-001", 100000m);
        ledger.Credit(50000m);
        ledger.Debit(20000m);
        Console.WriteLine($"Saldo Akhir: Rp {ledger.Balance:N0}");
    }
}
